from rdkit import Chem
import numpy as np
m=Chem.MolFromMolFile('initial.mol',removeHs=False);p=np.loadtxt('refined.xyz',skiprows=2,usecols=(1,2,3));q=m.GetConformer().GetPositions()
for a,b in [(0,43),(43,44),(43,2),(43,16),(43,30),(0,65),(0,1),(0,15),(0,29),(44,45),(44,53),(53,54)]: print(a,b,np.linalg.norm(p[a]-p[b]))
for b in m.GetBonds():
 i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx(); d=np.linalg.norm(p[i]-p[j]); d0=np.linalg.norm(q[i]-q[j]);
 if abs(d/d0-1)>.15: print('change',i,j,b.GetBondType(),round(d0,2),round(d,2))
# Check nonbonded covalent radius closeness
pt=Chem.GetPeriodicTable()
for i in range(len(p)):
 for j in range(i):
  if m.GetBondBetweenAtoms(i,j):continue
  ai=m.GetAtomWithIdx(i);aj=m.GetAtomWithIdx(j);d=np.linalg.norm(p[i]-p[j]);cut=(pt.GetRcovalent(ai.GetAtomicNum())+pt.GetRcovalent(aj.GetAtomicNum()))*1.2
  if d<cut:print('close',i,j,ai.GetSymbol(),aj.GetSymbol(),round(d,3))
